insert into public.series
  (id, slug, title, description, poster_url, release_year, status, episode_count, genres, tags, is_ai_original, badge, trending_rank, is_published)
values
  ('10000000-0000-4000-8000-000000000001','the-ceos-second-chance','The CEO''s Second Chance','After a painful breakup, she unexpectedly reunites with her cold CEO ex—but this time, he''s the one changing.','/images/poster-1.svg',2026,'ongoing',50,array['Romance','Drama']::text[],array['Second chance','Slow burn','Secrets']::text[],true,'AI ORIGINAL',1,true),
  ('10000000-0000-4000-8000-000000000002','my-ai-boyfriend','My AI Boyfriend','A lonely engineer builds the perfect companion, then discovers he remembers a life he never lived.','/images/poster-2.svg',2026,'ongoing',30,array['Sci-Fi','Romance']::text[],array['Artificial intelligence','Memory']::text[],false,'TRENDING',2,true),
  ('10000000-0000-4000-8000-000000000003','bound-by-revenge','Bound by Revenge','She returned to take back an empire. Falling for its heir was never part of the plan.','/images/poster-3.svg',2026,'ongoing',42,array['Drama']::text[],array['Revenge','Empire']::text[],false,null,3,true),
  ('10000000-0000-4000-8000-000000000004','moonlit-oath','Moonlit Oath','An immortal warrior and a royal seer are bound by a forbidden promise.','/images/poster-4.svg',2025,'completed',36,array['Fantasy']::text[],array['Immortal','Royal']::text[],false,null,4,true),
  ('10000000-0000-4000-8000-000000000005','the-perfect-alibi','The Perfect Alibi','Every witness saw him leave. Every camera says he stayed.','/images/poster-5.svg',2026,'ongoing',24,array['Mystery']::text[],array['Crime','Secrets']::text[],false,null,5,true),
  ('10000000-0000-4000-8000-000000000006','stolen-crown','Stolen Crown','A servant with a royal secret risks everything to reclaim her name.','/images/poster-6.svg',2025,'completed',48,array['Historical']::text[],array['Royal','Identity']::text[],false,null,6,true),
  ('10000000-0000-4000-8000-000000000007','neon-hearts','Neon Hearts','Love is illegal in the city of tomorrow.','/images/poster-7.svg',2026,'ongoing',32,array['Sci-Fi']::text[],array['Dystopia','Forbidden love']::text[],false,null,7,true),
  ('10000000-0000-4000-8000-000000000008','contracted-to-love','Contracted to Love','A six-month contract. One rule: do not fall in love.','/images/poster-8.svg',2026,'ongoing',40,array['Romance']::text[],array['Contract','Slow burn']::text[],false,null,8,true)
